const causes = await browserjs(tabId, () => {
  // Let's find all the result items
  // Usually there are headings or containers for each cause
  const headings = Array.from(document.querySelectorAll("main h3, .symptom-results h3, #causes h3"));
  return headings.map(h => {
    const title = h.textContent?.trim();
    const link = h.querySelector("a")?.href;
    // let's find sibling or nearby associated factors
    let next = h.nextElementSibling;
    let factors = [];
    while (next && next.tagName !== 'H3' && next.tagName !== 'H2') {
      factors.push(next.textContent?.trim());
      next = next.nextElementSibling;
    }
    return { title, link, details: factors.join(" | ") };
  });
});
