const causes = await browserjs(tabId, () => {
  // Let's find all the result items
  // Usually there are headings or containers for each cause
  const headings = Array.from(document.querySelectorAll("main h3, .symptom-results h3, #causes h3"));
  return headings.map(h => {
    const title = h.textContent?.trim();
