    // let's find sibling or nearby associated factors
    let next = h.nextElementSibling;
    let factors = [];
    while (next && next.tagName !== 'H3' && next.tagName !== 'H2') {
      factors.push(next.textContent?.trim());
      next = next.nextElementSibling;
    }
    return { title, link, details: factors.join(" | ") };
  });
});
